    slug: "aab-gosht-milk-curry",
    title: "Aab Gosht: The Milk Curry of the Wazwan",
    author: "Wazwan Way Team",
    date: "October 15, 2026",
    updatedDate: "October 17, 2026",
    category: "Heritage Cookery",
